//! Wolfram exact linear-algebra replay across the compute audit envelope.
//!
//! The fixture (`sonium-qa/wolfram/goldens/exact-linear-algebra-v1.json`,
//! generated by `sonium-qa/wolfram/exact_linear_algebra.wls`) carries exact
//! matrices with independent NoTrans/Trans/ConjTrans references, per
//! audit-sonium-compute-20260921: awkward strides, cancellation-sensitive
//! reductions, rectangular SpMV/SpMM, and Hermitian/transpose actions
//! compared on the same independent reference. Zero-dimension admission
//! and non-finite contracts are encoded alongside (no Wolfram math to
//! derive; the documented kernel contract is the oracle).

use num_complex::Complex64;
use serde::Deserialize;
use sonium_compute::backend::Transpose;
use sonium_compute::cpu::blas1::{dot_f64, dotc_c64, nrm2_f64};
use sonium_compute::cpu::blas2::{gemv_c64, gemv_f64};
use sonium_compute::{
    AdjointDeviceCsr, Backend, BackendError, CpuBackend, DeviceAdjointOperator, DeviceBufferLike,
    DeviceCsr, HostCsrRef, PersistentDeviceCsr,
};

const FIXTURE: &str = include_str!("../../sonium-qa/wolfram/goldens/exact-linear-algebra-v1.json");

#[derive(Debug, Deserialize)]
struct ComplexScalar {
    re: String,
    im: String,
}

#[derive(Debug, Deserialize)]
struct RealAction {
    a: Vec<Vec<String>>,
    x_exact: Vec<String>,
    b: Vec<String>,
    atx: Vec<String>,
    y: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct ComplexAction {
    a: Vec<Vec<ComplexScalar>>,
    v: Vec<ComplexScalar>,
    hv: Vec<ComplexScalar>,
    hermitian_v: Vec<ComplexScalar>,
    transpose_v: Vec<ComplexScalar>,
}

#[derive(Debug, Deserialize)]
struct StridedRealAction {
    a: Vec<Vec<String>>,
    x: Vec<String>,
    b: Vec<String>,
    y: Vec<String>,
    atx: Vec<String>,
    lda: usize,
}

#[derive(Debug, Deserialize)]
struct StridedComplexAction {
    a: Vec<Vec<ComplexScalar>>,
    x: Vec<ComplexScalar>,
    b: Vec<ComplexScalar>,
    y: Vec<ComplexScalar>,
    hermitian_y: Vec<ComplexScalar>,
    transpose_y: Vec<ComplexScalar>,
    lda: usize,
}

#[derive(Debug, Deserialize)]
struct ReductionExact {
    dot_u: Vec<String>,
    dot_v: Vec<String>,
    dot: String,
    norm_w: Vec<String>,
    norm2: String,
    cdot_p: Vec<ComplexScalar>,
    cdot_q: Vec<ComplexScalar>,
    dot_conj: ComplexScalar,
    #[allow(dead_code)]
    dot_plain: ComplexScalar,
}

#[derive(Debug, Deserialize)]
struct ReductionCancellation {
    x: Vec<String>,
    y: Vec<String>,
    exact: String,
    bound: String,
}

#[derive(Debug, Deserialize)]
struct CsrAction {
    row_ptr: Vec<i32>,
    col_idx: Vec<i32>,
    values: Vec<String>,
    x: Vec<String>,
    y: Vec<String>,
    xt: Vec<String>,
    at_xt: Vec<String>,
    x_rhs: Vec<Vec<String>>,
    y_rhs: Vec<Vec<String>>,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    schema: String,
    nonsym_3x3: RealAction,
    rect_4x3: RealAction,
    hermitian_3x3: ComplexAction,
    strided_gemv_3x4: StridedRealAction,
    strided_gemv_c64_2x3: StridedComplexAction,
    reduction_exact: ReductionExact,
    reduction_cancellation: ReductionCancellation,
    csr_spmv_2x3: CsrAction,
}

fn parse(value: &str) -> f64 {
    value.parse().expect("fixture value is a decimal")
}

fn parse_complex(value: &ComplexScalar) -> Complex64 {
    Complex64::new(parse(&value.re), parse(&value.im))
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture =
        serde_json::from_str(FIXTURE).expect("valid exact linear-algebra fixture");
    assert_eq!(fixture.schema, "sonium-qa.exact-linear-algebra.v1");
    fixture
}

fn flat_real(rows: &[Vec<String>]) -> Vec<f64> {
    rows.iter()
        .flat_map(|row| row.iter().map(|value| parse(value)))
        .collect()
}

fn run_gemv_f64(op: Transpose, rows: &[Vec<String>], x: &[f64]) -> Vec<f64> {
    // Row-major contract: NoTrans takes (m, n) matrix dims; Trans/ConjTrans
    // take swapped dims over the same row-major storage with lda = row
    // stride (see cpu::blas2 row-major Trans contract).
    let (m, n) = (rows.len(), rows[0].len());
    let a = flat_real(rows);
    let (call_m, call_n) = match op {
        Transpose::NoTrans => (m, n),
        Transpose::Trans | Transpose::ConjTrans => (n, m),
    };
    let mut y = vec![0.0; call_m];
    gemv_f64(op, call_m, call_n, 1.0, &a, n, x, 0.0, &mut y);
    y
}

fn assert_close(actual: &[f64], expected: &[String], label: &str) {
    assert_eq!(actual.len(), expected.len(), "{label}: length mismatch");
    for (index, (&got, want)) in actual.iter().zip(expected).enumerate() {
        let want = parse(want);
        assert!(
            (got - want).abs() <= 1e-12 * want.abs().max(1.0),
            "{label}[{index}]: {got:e} != {want:e}"
        );
    }
}

#[test]
fn gemv_f64_notrans_matches_wolfram() {
    let fixture = parse_fixture();
    for (label, case) in [("nonsym", &fixture.nonsym_3x3), ("rect", &fixture.rect_4x3)] {
        let x: Vec<f64> = case.x_exact.iter().map(|value| parse(value)).collect();
        let actual = run_gemv_f64(Transpose::NoTrans, &case.a, &x);
        assert_close(&actual, &case.b, &format!("{label} NoTrans"));
    }
}

#[test]
fn gemv_f64_trans_matches_wolfram() {
    let fixture = parse_fixture();
    for (label, case) in [("nonsym", &fixture.nonsym_3x3), ("rect", &fixture.rect_4x3)] {
        let y: Vec<f64> = case.y.iter().map(|value| parse(value)).collect();
        let actual = run_gemv_f64(Transpose::Trans, &case.a, &y);
        assert_close(&actual, &case.atx, &format!("{label} Trans"));
        // Real types: ConjTrans must behave identically to Trans.
        let actual_conj = run_gemv_f64(Transpose::ConjTrans, &case.a, &y);
        assert_close(&actual_conj, &case.atx, &format!("{label} ConjTrans"));
    }
}

#[test]
fn gemv_c64_variants_match_wolfram() {
    let fixture = parse_fixture();
    let case = &fixture.hermitian_3x3;
    let a: Vec<Complex64> = case
        .a
        .iter()
        .flat_map(|row| row.iter().map(parse_complex))
        .collect();
    let v: Vec<Complex64> = case.v.iter().map(parse_complex).collect();
    let run = |op: Transpose| {
        let mut y = vec![Complex64::new(0.0, 0.0); 3];
        gemv_c64(
            op,
            3,
            3,
            Complex64::new(1.0, 0.0),
            &a,
            3,
            &v,
            Complex64::new(0.0, 0.0),
            &mut y,
        );
        y
    };
    let check = |actual: &[Complex64], expected: &[ComplexScalar], label: &str| {
        assert_eq!(actual.len(), expected.len(), "{label}: length mismatch");
        for (index, (got, want)) in actual.iter().zip(expected).enumerate() {
            let want = parse_complex(want);
            assert!(
                (got - want).norm() <= 1e-12 * want.norm().max(1.0),
                "{label}[{index}]: {got:?} != {want:?}"
            );
        }
    };
    check(&run(Transpose::NoTrans), &case.hv, "c64 NoTrans");
    check(
        &run(Transpose::ConjTrans),
        &case.hermitian_v,
        "c64 ConjTrans",
    );
    check(&run(Transpose::Trans), &case.transpose_v, "c64 Trans");
}

fn assert_exact(actual: &[f64], expected: &[String], label: &str) {
    assert_eq!(actual.len(), expected.len(), "{label}: length mismatch");
    for (index, (&got, want)) in actual.iter().zip(expected).enumerate() {
        let want = parse(want);
        // Exact small-integer arithmetic: every intermediate sum and
        // product is exactly representable, so any summation order
        // (scalar, AVX2, NEON, FMA) must reproduce the oracle bit-for-bit.
        assert!(
            got == want,
            "{label}[{index}]: {got:e} != {want:e} (must be exact)"
        );
    }
}

fn pad_real(rows: &[Vec<String>], lda: usize) -> Vec<f64> {
    let mut flat = Vec::with_capacity(rows.len() * lda);
    for row in rows {
        assert!(lda >= row.len(), "fixture lda must cover the row");
        flat.extend(row.iter().map(|value| parse(value)));
        flat.extend(std::iter::repeat_n(0.0, lda - row.len()));
    }
    flat
}

fn pad_complex(rows: &[Vec<ComplexScalar>], lda: usize) -> Vec<Complex64> {
    let mut flat = Vec::with_capacity(rows.len() * lda);
    for row in rows {
        assert!(lda >= row.len(), "fixture lda must cover the row");
        flat.extend(row.iter().map(parse_complex));
        flat.extend(std::iter::repeat_n(
            Complex64::new(0.0, 0.0),
            lda - row.len(),
        ));
    }
    flat
}

#[test]
fn gemv_f64_strided_matches_wolfram() {
    let fixture = parse_fixture();
    let case = &fixture.strided_gemv_3x4;
    let a = pad_real(&case.a, case.lda);
    let x: Vec<f64> = case.x.iter().map(|value| parse(value)).collect();
    let mut y = vec![0.0; 3];
    gemv_f64(Transpose::NoTrans, 3, 4, 1.0, &a, case.lda, &x, 0.0, &mut y);
    assert_exact(&y, &case.b, "strided NoTrans");
    let yt: Vec<f64> = case.y.iter().map(|value| parse(value)).collect();
    let mut out = vec![0.0; 4];
    gemv_f64(
        Transpose::Trans,
        4,
        3,
        1.0,
        &a,
        case.lda,
        &yt,
        0.0,
        &mut out,
    );
    assert_exact(&out, &case.atx, "strided Trans");
}

#[test]
fn gemv_c64_strided_matches_wolfram() {
    let fixture = parse_fixture();
    let case = &fixture.strided_gemv_c64_2x3;
    let a = pad_complex(&case.a, case.lda);
    let x: Vec<Complex64> = case.x.iter().map(parse_complex).collect();
    let run = |op: Transpose, m: usize, n: usize, input: &[Complex64]| {
        let mut y = vec![Complex64::new(0.0, 0.0); m];
        gemv_c64(
            op,
            m,
            n,
            Complex64::new(1.0, 0.0),
            &a,
            case.lda,
            input,
            Complex64::new(0.0, 0.0),
            &mut y,
        );
        y
    };
    let check = |actual: &[Complex64], expected: &[ComplexScalar], label: &str| {
        assert_eq!(actual.len(), expected.len(), "{label}: length mismatch");
        for (index, (got, want)) in actual.iter().zip(expected).enumerate() {
            let want = parse_complex(want);
            assert!(
                got == &want,
                "{label}[{index}]: {got:?} != {want:?} (must be exact)"
            );
        }
    };
    check(
        &run(Transpose::NoTrans, 2, 3, &x),
        &case.b,
        "c64 strided NoTrans",
    );
    let y: Vec<Complex64> = case.y.iter().map(parse_complex).collect();
    check(
        &run(Transpose::ConjTrans, 3, 2, &y),
        &case.hermitian_y,
        "c64 strided ConjTrans",
    );
    check(
        &run(Transpose::Trans, 3, 2, &y),
        &case.transpose_y,
        "c64 strided Trans",
    );
}

#[test]
fn reductions_exact_match_wolfram() {
    let fixture = parse_fixture();
    let case = &fixture.reduction_exact;
    let u: Vec<f64> = case.dot_u.iter().map(|value| parse(value)).collect();
    let v: Vec<f64> = case.dot_v.iter().map(|value| parse(value)).collect();
    assert_eq!(dot_f64(&u, &v), parse(&case.dot), "exact dot");
    let w: Vec<f64> = case.norm_w.iter().map(|value| parse(value)).collect();
    assert_eq!(nrm2_f64(&w), parse(&case.norm2), "exact nrm2");
    let p: Vec<Complex64> = case.cdot_p.iter().map(parse_complex).collect();
    let q: Vec<Complex64> = case.cdot_q.iter().map(parse_complex).collect();
    assert_eq!(
        dotc_c64(&p, &q),
        parse_complex(&case.dot_conj),
        "exact dotc"
    );
}

#[test]
fn reduction_cancellation_within_documented_bound() {
    let fixture = parse_fixture();
    let case = &fixture.reduction_cancellation;
    let x: Vec<f64> = case.x.iter().map(|value| parse(value)).collect();
    let y: Vec<f64> = case.y.iter().map(|value| parse(value)).collect();
    let got = dot_f64(&x, &y);
    let exact = parse(&case.exact);
    let bound = parse(&case.bound);
    assert!(
        got.is_finite(),
        "cancellation reduction must stay finite, got {got:e}"
    );
    // The oracle value is exact (1); f64 accumulation is only bound-bound
    // (naive order yields 0). The bound is n*eps*|x|.|y| from the fixture.
    assert!(
        (got - exact).abs() <= bound,
        "cancellation: {got:e} exceeds bound {bound:e} around {exact:e}"
    );
}

fn cpu_buffers(
    backend: &CpuBackend,
    x_host: &[f64],
    y_len: usize,
) -> (
    <CpuBackend as Backend>::Buffer<f64>,
    <CpuBackend as Backend>::Buffer<f64>,
) {
    let mut x_buf = backend.raw_alloc::<f64>(x_host.len()).unwrap();
    backend.copy_h2d(x_host, &mut x_buf);
    let y_buf = backend.raw_alloc::<f64>(y_len).unwrap();
    (x_buf, y_buf)
}

fn download(backend: &CpuBackend, y_buf: &<CpuBackend as Backend>::Buffer<f64>) -> Vec<f64> {
    let mut y = vec![0.0; y_buf.len()];
    backend.copy_d2h(y_buf, &mut y);
    y
}

#[test]
fn csr_spmv_rectangular_matches_wolfram() {
    let fixture = parse_fixture();
    let case = &fixture.csr_spmv_2x3;
    let backend = CpuBackend::new();
    let values: Vec<f64> = case.values.iter().map(|value| parse(value)).collect();
    let matrix = DeviceCsr::try_from_host(&backend, 2, 3, &case.row_ptr, &case.col_idx, &values)
        .expect("rectangular fixture upload");
    let persistent =
        PersistentDeviceCsr::try_from_device_csr(&backend, matrix).expect("rectangular prebake");
    let x: Vec<f64> = case.x.iter().map(|value| parse(value)).collect();
    let (x_buf, mut y_buf) = cpu_buffers(&backend, &x, 2);
    persistent
        .try_apply(&backend, &x_buf, &mut y_buf)
        .expect("rectangular SpMV");
    assert_exact(&download(&backend, &y_buf), &case.y, "csr SpMV 2x3");
}

#[test]
fn csr_spmm_rectangular_matches_wolfram() {
    let fixture = parse_fixture();
    let case = &fixture.csr_spmv_2x3;
    let backend = CpuBackend::new();
    let values: Vec<f64> = case.values.iter().map(|value| parse(value)).collect();
    let matrix = DeviceCsr::try_from_host(&backend, 2, 3, &case.row_ptr, &case.col_idx, &values)
        .expect("rectangular fixture upload");
    let persistent =
        PersistentDeviceCsr::try_from_device_csr(&backend, matrix).expect("rectangular prebake");
    // Column-major RHS: each column is one right-hand side.
    let mut x_colmajor = Vec::with_capacity(6);
    for col in 0..2 {
        for row in &case.x_rhs {
            x_colmajor.push(parse(&row[col]));
        }
    }
    let (x_buf, mut y_buf) = cpu_buffers(&backend, &x_colmajor, 4);
    persistent
        .try_apply_colmajor(&backend, 2, &x_buf, &mut y_buf)
        .expect("rectangular SpMM");
    let mut expected_colmajor = Vec::with_capacity(4);
    for col in 0..2 {
        for row in &case.y_rhs {
            expected_colmajor.push(row[col].clone());
        }
    }
    assert_exact(
        &download(&backend, &y_buf),
        &expected_colmajor,
        "csr SpMM 2x3x2",
    );
}

#[test]
fn csr_transpose_matches_wolfram() {
    let fixture = parse_fixture();
    let case = &fixture.csr_spmv_2x3;
    let backend = CpuBackend::new();
    let values: Vec<f64> = case.values.iter().map(|value| parse(value)).collect();
    let row_ptr: Vec<usize> = case.row_ptr.iter().map(|&v| v as usize).collect();
    let col_idx: Vec<usize> = case.col_idx.iter().map(|&v| v as usize).collect();
    // Rectangular path: explicit host transpose, then an ordinary SpMV.
    let host = HostCsrRef::new(2, 3, &row_ptr, &col_idx, &values);
    let transposed = host.try_transpose().expect("rectangular transpose");
    let matrix = DeviceCsr::try_from_host_csr_ref(&backend, transposed.as_ref())
        .expect("transposed fixture upload");
    let persistent =
        PersistentDeviceCsr::try_from_device_csr(&backend, matrix).expect("transposed prebake");
    let xt: Vec<f64> = case.xt.iter().map(|value| parse(value)).collect();
    let (x_buf, mut y_buf) = cpu_buffers(&backend, &xt, 3);
    persistent
        .try_apply(&backend, &x_buf, &mut y_buf)
        .expect("transposed SpMV");
    assert_exact(&download(&backend, &y_buf), &case.at_xt, "csr A^T 3x2");
    // Square path: the adjoint operator builds A^H itself (A^H = A^T
    // over the reals) and applies it without host transfers.
    let nonsym = &fixture.nonsym_3x3;
    let n_values: Vec<f64> = flat_real(&nonsym.a)
        .into_iter()
        .enumerate()
        .filter(|(_, v)| *v != 0.0)
        .map(|(_, v)| v)
        .collect();
    let n_row_ptr = vec![0usize, 2, 5, 7];
    let n_col_idx = vec![0usize, 1, 0, 1, 2, 1, 2];
    assert_eq!(n_values, vec![2.0, 1.0, -1.0, 3.0, 1.0, -2.0, 4.0]);
    let n_host = HostCsrRef::new(3, 3, &n_row_ptr, &n_col_idx, &n_values);
    let adjoint =
        AdjointDeviceCsr::try_from_host_csr_ref(&backend, n_host).expect("adjoint fixture upload");
    let ny: Vec<f64> = nonsym.y.iter().map(|value| parse(value)).collect();
    let (nx_buf, mut ny_buf) = cpu_buffers(&backend, &ny, 3);
    adjoint
        .try_apply_hermitian(&backend, &nx_buf, &mut ny_buf)
        .expect("adjoint apply");
    assert_exact(&download(&backend, &ny_buf), &nonsym.atx, "csr A^H 3x3");
}

#[test]
fn zero_dimensions_admitted() {
    // Empty-row GEMV is a no-op over an empty output; it must not panic
    // or read the (absent) matrix rows.
    let mut y_empty: Vec<f64> = Vec::new();
    gemv_f64(
        Transpose::NoTrans,
        0,
        3,
        1.0,
        &[],
        3,
        &[1.0, 2.0, 3.0],
        0.0,
        &mut y_empty,
    );
    assert!(y_empty.is_empty(), "0x3 GEMV must produce no output");
    // Empty-column GEMV scales the output by beta (0 here) without
    // touching the empty inner dimension.
    let mut y_zeros = vec![7.0; 3];
    gemv_f64(
        Transpose::NoTrans,
        3,
        0,
        1.0,
        &[],
        0,
        &[],
        0.0,
        &mut y_zeros,
    );
    assert_eq!(y_zeros, vec![0.0; 3], "3x0 GEMV must zero the output");
    // Empty-row CSR uploads and applies through the checked path.
    let backend = CpuBackend::new();
    let matrix = DeviceCsr::try_from_host(&backend, 0, 3, &[0], &[], &[]).expect("0x3 CSR upload");
    let persistent =
        PersistentDeviceCsr::try_from_device_csr(&backend, matrix).expect("0x3 prebake");
    let (x_buf, mut y_buf) = cpu_buffers(&backend, &[1.0, 2.0, 3.0], 0);
    persistent
        .try_apply(&backend, &x_buf, &mut y_buf)
        .expect("0x3 SpMV");
    assert!(download(&backend, &y_buf).is_empty(), "0x3 SpMV is empty");
}

#[test]
fn nonfinite_contracts() {
    // Raw kernels propagate NaN (BLAS semantics): 0*NaN is NaN, never
    // silently skipped, matching the transpose-GEMV fix.
    let mut y = vec![0.0];
    gemv_f64(
        Transpose::NoTrans,
        1,
        1,
        1.0,
        &[f64::NAN],
        1,
        &[0.0],
        0.0,
        &mut y,
    );
    assert!(y[0].is_nan(), "0*NaN must propagate through GEMV");
    assert!(
        dot_f64(&[f64::NAN, 1.0], &[1.0, 1.0]).is_nan(),
        "NaN must propagate through dot"
    );
    // Checked sparse admission instead rejects non-finite data with
    // typed errors: matrix values at upload, input vectors at apply.
    let backend = CpuBackend::new();
    let error = match DeviceCsr::try_from_host(
        &backend,
        2,
        2,
        &[0, 2, 4],
        &[0, 1, 0, 1],
        &[4.0, 1.0, f64::NAN, 3.0],
    ) {
        Ok(_) => panic!("NaN matrix values must be rejected at upload"),
        Err(error) => error,
    };
    assert!(
        matches!(error, BackendError::InvalidArgument { .. }),
        "expected InvalidArgument, got {error:?}"
    );
    let matrix_ok = DeviceCsr::try_from_host(
        &backend,
        2,
        2,
        &[0, 2, 4],
        &[0, 1, 0, 1],
        &[4.0, 1.0, 1.0, 3.0],
    )
    .expect("finite fixture upload");
    let persistent_ok =
        PersistentDeviceCsr::try_from_device_csr(&backend, matrix_ok).expect("finite prebake");
    let (nan_x_buf, mut y_buf2) = cpu_buffers(&backend, &[1.0, f64::INFINITY], 2);
    let error = persistent_ok
        .try_apply(&backend, &nan_x_buf, &mut y_buf2)
        .expect_err("non-finite input vector must be rejected");
    assert!(
        matches!(error, BackendError::OperationFailed { .. }),
        "expected OperationFailed, got {error:?}"
    );
}
